using Agro360.Application.Contracts;
using Agro360.Infrastructure.Persistence;
using Agro360.Multitenancy;
using Agro360.SharedKernel;
using Dapper;
using Npgsql;
using Microsoft.Extensions.Logging;

namespace Agro360.Infrastructure.Services;

public sealed class Livestock360Service(DatabaseExecutor db, ITenantContext tenant, ILogger<Livestock360Service> logger) : ILivestock360Service
{
    public Task<dynamic?> GetAnimalAsync(Guid id,CancellationToken ct)=>Tx<dynamic>(async(c,t)=>await c.QuerySingleOrDefaultAsync(new CommandDefinition("select * from agro360.livestock_animals where tenant_id=@TenantId and id=@Id and deleted_at is null",new{tenant.TenantId,Id=id},t,cancellationToken:ct)));
    public Task<dynamic> UpdateAnimalAsync(Guid id,RegisterAnimalCommand command,CancellationToken ct)=>Tx<dynamic>(async(c,t)=>{ ValidateWeight(null); var n=await c.ExecuteAsync(new CommandDefinition("update agro360.livestock_animals set farm_id=@FarmId,herd_id=@HerdId,tag=@Tag,rfid=@Rfid,species=@Species,breed=@Breed,sex=@Sex,birth_date=@BirthDate,mother_id=@MotherId,father_id=@FatherId,updated_at=now(),updated_by=@UserId,version=version+1 where tenant_id=@TenantId and id=@Id",new{command.FarmId,command.HerdId,Tag=Guard.Required(command.Tag,nameof(command.Tag),80),command.Rfid,command.Species,command.Breed,command.Sex,command.BirthDate,command.MotherId,command.FatherId,tenant.TenantId,tenant.UserId,Id=id},t,cancellationToken:ct));if(n==0)throw new NotFoundException("Animal",id);await Audit(c,t,"update","Animal",id,command,ct);return await c.QuerySingleAsync(new CommandDefinition("select * from agro360.livestock_animals where tenant_id=@TenantId and id=@Id",new{tenant.TenantId,Id=id},t,cancellationToken:ct));});
    public Task ChangeAnimalStatusAsync(Guid id,string status,AnimalStatusCommand command,CancellationToken ct)=>Tx(async(c,t)=>{var code=status switch{"DEAD"=>4,"SOLD"=>3,"DISCARDED"=>5,_=>throw new DomainException("Status inválido.","agro360.livestock_status_invalid")};var n=await c.ExecuteAsync(new CommandDefinition("update agro360.livestock_animals set status=@Code,updated_at=now(),updated_by=@UserId,version=version+1 where tenant_id=@TenantId and id=@Id and status in (1,2,6); insert into agro360.livestock_animal_events(id,tenant_id,animal_id,event_type,occurred_on,data,created_at,created_by) select @EventId,@TenantId,@Id,@Status,@On,jsonb_build_object('reason',@Reason),now(),@UserId where exists(select 1 from agro360.livestock_animals where tenant_id=@TenantId and id=@Id and status=@Code)",new{Code=code,tenant.TenantId,tenant.UserId,Id=id,EventId=Guid.CreateVersion7(),Status=status,On=command.OccurredOn,command.Reason},t,cancellationToken:ct));if(n<2)throw new ConflictException("Animal inexistente ou inativo.","agro360.livestock_animal_not_active");await Audit(c,t,status.ToLowerInvariant(),"Animal",id,command,ct);});
    public Task TransferAnimalAsync(Guid id,AnimalTransferCommand command,CancellationToken ct)=>Tx(async(c,t)=>{var old=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select farm_id,paddock_id,status from agro360.livestock_animals where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=id},t,cancellationToken:ct))??throw new NotFoundException("Animal",id);await c.ExecuteAsync(new CommandDefinition("update agro360.livestock_animals set farm_id=@FarmId,paddock_id=@PaddockId,updated_at=now(),updated_by=@UserId,version=version+1 where tenant_id=@TenantId and id=@Id; insert into agro360.livestock_animal_movements(id,tenant_id,animal_id,from_farm_id,to_farm_id,from_paddock_id,to_paddock_id,moved_on,notes,created_at,created_by) values(@Movement,@TenantId,@Id,@OldFarm,@FarmId,@OldPaddock,@PaddockId,@On,@Notes,now(),@UserId)",new{command.FarmId,command.PaddockId,tenant.TenantId,tenant.UserId,Id=id,Movement=Guid.CreateVersion7(),OldFarm=(Guid)old.farm_id,OldPaddock=(Guid?)old.paddock_id,On=command.OccurredOn,command.Notes},t,cancellationToken:ct));await Audit(c,t,"transfer","Animal",id,command,ct);});
    public Task<IReadOnlyList<dynamic>> ListHerdsAsync(CancellationToken ct)=>List("select id, farm_id as \"farmId\", name, species, category, head_count as \"headCount\", status from agro360.livestock_herds where tenant_id=@TenantId and status='ACTIVE' and deleted_at is null order by name",ct);
    public Task<Guid> SaveHerdAsync(Guid? id,HerdCommand command,CancellationToken ct)=>Upsert("agro360.livestock_herds",id,"farm_id,name,species,category,head_count,status","@FarmId,@Name,@Species,@Category,@HeadCount,'ACTIVE'","farm_id=@FarmId,name=@Name,species=@Species,category=@Category,head_count=@HeadCount,status='ACTIVE'",command,ct);
    public Task<IReadOnlyList<dynamic>> ListPasturesAsync(CancellationToken ct)=>List("select p.*,count(k.id) paddocks from agro360.livestock_pastures p left join agro360.livestock_paddocks k on k.pasture_id=p.id where p.tenant_id=@TenantId group by p.id order by p.name",ct);
    public Task<Guid> SavePastureAsync(Guid? id,PastureCommand command,CancellationToken ct){if(command.AreaHectares<=0)throw new DomainException("Área deve ser positiva.","agro360.pasture_area_invalid");return Upsert("agro360.livestock_pastures",id,"farm_id,name,area_hectares,forage_type,status","@FarmId,@Name,@AreaHectares,@ForageType,@Status","farm_id=@FarmId,name=@Name,area_hectares=@AreaHectares,forage_type=@ForageType,status=@Status",command,ct);}
    public Task<IReadOnlyList<dynamic>> ListPaddocksAsync(CancellationToken ct)=>List("select p.*,coalesce(o.occupancy,0) occupancy,(coalesce(o.occupancy,0)>p.capacity_au) overcapacity from agro360.livestock_paddocks p left join lateral(select count(*) occupancy from agro360.livestock_animals a where a.tenant_id=p.tenant_id and a.paddock_id=p.id and a.status in(1,2,6))o on true where p.tenant_id=@TenantId order by p.name",ct);
    public Task<Guid> SavePaddockAsync(Guid? id,PaddockCommand command,CancellationToken ct){if(command.AreaHectares<=0||command.CapacityAu<0||command.RestDays<0||command.OccupationDays<0)throw new DomainException("Valores de piquete inválidos.","agro360.pasture_values_invalid");return Upsert("agro360.livestock_paddocks",id,"pasture_id,name,area_hectares,capacity_au,status,rest_days,occupation_days,entry_height_cm,exit_height_cm,forage_mass_kg_ha","@PastureId,@Name,@AreaHectares,@CapacityAu,@Status,@RestDays,@OccupationDays,@EntryHeightCm,@ExitHeightCm,@ForageMassKgHa","pasture_id=@PastureId,name=@Name,area_hectares=@AreaHectares,capacity_au=@CapacityAu,status=@Status,rest_days=@RestDays,occupation_days=@OccupationDays,entry_height_cm=@EntryHeightCm,exit_height_cm=@ExitHeightCm,forage_mass_kg_ha=@ForageMassKgHa",command,ct);}
    public Task MovePaddockAsync(Guid id,bool occupy,PaddockMovementCommand command,CancellationToken ct)=>Tx(async(c,t)=>{var p=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select status,last_released_at,rest_days from agro360.livestock_paddocks where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=id},t,cancellationToken:ct))??throw new NotFoundException("Piquete",id);if(occupy&&((string)p.status=="INACTIVE"||(string)p.status=="INATIVA"))throw new ConflictException("Piquete inativo não pode ser ocupado.","agro360.pasture_inactive");if(command.AnimalId is null&&command.HerdId is null)throw new DomainException("Informe animal ou lote.","agro360.livestock_subject_required");var eventId=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_paddock_movements(id,tenant_id,paddock_id,origin_paddock_id,animal_id,herd_id,movement_type,occurred_at,notes,created_by) values(@EventId,@TenantId,@Id,@Origin,@Animal,@Herd,@Type,@At,@Notes,@UserId); update agro360.livestock_paddocks set status=@Status,last_occupied_at=case when @Occupy then @At else last_occupied_at end,last_released_at=case when @Occupy then last_released_at else @At end,updated_at=now() where tenant_id=@TenantId and id=@Id; update agro360.livestock_animals set paddock_id=case when @Occupy then @Id else null end,updated_at=now(),version=version+1 where tenant_id=@TenantId and ((@Animal is not null and id=@Animal) or (@Herd is not null and herd_id=@Herd))",new{EventId=eventId,tenant.TenantId,Id=id,Origin=command.OriginPaddockId,Animal=command.AnimalId,Herd=command.HerdId,Type=occupy?"ENTRY":"EXIT",At=command.OccurredAt,command.Notes,tenant.UserId,Status=occupy?"IN_USE":"RESTING",Occupy=occupy},t,cancellationToken:ct));await Audit(c,t,occupy?"occupy":"release","Paddock",id,command,ct);});
    public Task<IReadOnlyList<dynamic>> ListEventsAsync(string kind,CancellationToken ct){var table=kind switch{"handling"=>"handling_events","health"=>"health_events","reproduction"=>"reproduction_events",_=>throw new DomainException("Tipo inválido.","agro360.livestock_event_type_invalid")};return List($"select * from agro360.livestock_{table} where tenant_id=@TenantId order by occurred_on desc limit 500",ct);}
    public Task<Guid> AddHandlingAsync(HandlingEventCommand command,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{if(command.AnimalId is null&&command.HerdId is null)throw new DomainException("Informe animal ou lote.","agro360.livestock_subject_required");if(command.WeightKg<0||command.EstimatedCost<0)throw new DomainException("Peso e custo não podem ser negativos.","agro360.livestock_handling_values_invalid");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_handling_events(id,tenant_id,animal_id,herd_id,event_type,occurred_on,responsible,notes,weight_kg,body_score,paddock_id,estimated_cost,created_by) values(@Id,@TenantId,@AnimalId,@HerdId,@Type,@OccurredOn,@Responsible,@Notes,@WeightKg,@BodyScore,@PaddockId,@EstimatedCost,@UserId); update agro360.livestock_animals set current_weight_kg=coalesce(@WeightKg,current_weight_kg),last_weight_date=case when @WeightKg is null then last_weight_date else @OccurredOn end,status=case when upper(@Type)='MORTALITY' then 4 when upper(@Type)='SALE' then 3 when upper(@Type)='DISCARD' then 5 else status end,version=version+1,updated_at=now() where tenant_id=@TenantId and id=@AnimalId and status in(1,2,6)",new{Id=id,tenant.TenantId,command.AnimalId,command.HerdId,command.Type,command.OccurredOn,command.Responsible,command.Notes,command.WeightKg,command.BodyScore,command.PaddockId,command.EstimatedCost,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","HandlingEvent",id,command,ct);return id;});
    public Task<Guid> AddHealthAsync(HealthEventCommand command,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{if(command.Dose<=0)throw new DomainException("Dose deve ser positiva.","agro360.livestock_dose_invalid");if(command.WithdrawalDays<0)throw new DomainException("Carência inválida.","agro360.livestock_withdrawal_invalid");var id=Guid.CreateVersion7();await Consume(c,t,command.WarehouseId,command.ProductId,command.Dose,command.Unit,id,"HEALTH_EVENT",ct);await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_health_events(id,tenant_id,animal_id,herd_id,event_type,occurred_on,dose,unit,product_id,withdrawal_until,next_application,technician,diagnosis,notes,cost_amount,created_by) values(@Id,@TenantId,@AnimalId,@HerdId,@Type,@AppliedOn,@Dose,@Unit,@ProductId,@Withdrawal,@NextApplication,@Technician,@Diagnosis,@Notes,0,@UserId); update agro360.livestock_animals set withdrawal_until=greatest(coalesce(withdrawal_until,@Withdrawal),@Withdrawal),version=version+1,updated_at=now() where tenant_id=@TenantId and id=@AnimalId",new{Id=id,tenant.TenantId,command.AnimalId,command.HerdId,command.Type,command.AppliedOn,command.Dose,command.Unit,command.ProductId,Withdrawal=command.AppliedOn.AddDays(command.WithdrawalDays),command.NextApplication,command.Technician,command.Diagnosis,command.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","HealthEvent",id,command,ct);return id;});
    public Task<Guid> AddReproductionAsync(ReproductionEventCommand command,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{var female=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select sex,status,species,farm_id from agro360.livestock_animals where tenant_id=@TenantId and id=@Id for update",new{tenant.TenantId,Id=command.FemaleId},t,cancellationToken:ct))??throw new NotFoundException("Matriz",command.FemaleId);if(!new[]{"F","FEMALE","FEMEA","FÊMEA"}.Contains(((string)female.sex).ToUpperInvariant()))throw new DomainException("Somente fêmeas podem receber evento reprodutivo.","agro360.livestock_female_required");if((short)female.status is not (1 or 2 or 6))throw new ConflictException("Matriz não está ativa.");var type=command.Type.ToUpperInvariant();if(type is "INSEMINATION" or "NATURAL_SERVICE"){var active=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from agro360.livestock_reproduction_cycles where tenant_id=@TenantId and female_id=@FemaleId and status='ACTIVE')",new{tenant.TenantId,command.FemaleId},t,cancellationToken:ct));if(active)throw new ConflictException("Já existe ciclo reprodutivo ativo.","agro360.livestock_reproduction_conflict");}var id=Guid.CreateVersion7();DateOnly? due=type=="PREGNANCY_DIAGNOSIS"&&command.Positive==true?command.OccurredOn.AddDays(GestationDays((string)female.species)):null;await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_reproduction_events(id,tenant_id,female_id,sire_id,event_type,occurred_on,genetic_lot,positive,expected_birth_on,notes,created_by) values(@Id,@TenantId,@FemaleId,@SireId,@Type,@OccurredOn,@GeneticLot,@Positive,@Due,@Notes,@UserId); insert into agro360.livestock_reproduction_cycles(id,tenant_id,female_id,started_on,status,expected_birth_on,created_by) select @Cycle,@TenantId,@FemaleId,@OccurredOn,'ACTIVE',@Due,@UserId where @Type in('INSEMINATION','NATURAL_SERVICE'); update agro360.livestock_reproduction_cycles set expected_birth_on=@Due,status=case when @Positive=false then 'CLOSED' else status end,updated_at=now() where tenant_id=@TenantId and female_id=@FemaleId and status='ACTIVE' and @Type='PREGNANCY_DIAGNOSIS'; update agro360.livestock_reproduction_cycles set status='CLOSED',ended_on=@OccurredOn,updated_at=now() where tenant_id=@TenantId and female_id=@FemaleId and status='ACTIVE' and @Type in('BIRTH','ABORTION')",new{Id=id,tenant.TenantId,command.FemaleId,command.SireId,Type=type,command.OccurredOn,command.GeneticLot,command.Positive,Due=due,command.Notes,tenant.UserId,Cycle=Guid.CreateVersion7()},t,cancellationToken:ct));if(type=="BIRTH"&&command.CreateCalf){if(string.IsNullOrWhiteSpace(command.CalfTag))throw new DomainException("Identificação da cria é obrigatória.","agro360.livestock_calf_tag_required");await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_animals(id,tenant_id,farm_id,tag,species,breed,sex,birth_date,mother_id,status,created_at,created_by,version) values(@Calf,@TenantId,@Farm,@Tag,@Species,'NÃO INFORMADA','U',@Born,@Mother,1,now(),@UserId,1)",new{Calf=Guid.CreateVersion7(),tenant.TenantId,Farm=(Guid)female.farm_id,Tag=command.CalfTag,Species=(string)female.species,Born=command.OccurredOn,Mother=command.FemaleId,tenant.UserId},t,cancellationToken:ct));}await Audit(c,t,"create","ReproductionEvent",id,command,ct);return id;});
    public Task<IReadOnlyList<dynamic>> ListNutritionPlansAsync(CancellationToken ct)=>List("select p.*,coalesce(sum(i.quantity_per_day*i.unit_cost),0) daily_cost from agro360.livestock_nutrition_plans p left join agro360.livestock_nutrition_plan_items i on i.plan_id=p.id where p.tenant_id=@TenantId group by p.id order by p.starts_on desc",ct);
    public Task<Guid> AddNutritionPlanAsync(NutritionPlanCommand command,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{if(command.Items.Count==0||command.Items.Any(i=>i.QuantityPerDay<=0||i.UnitCost<0))throw new DomainException("Dieta deve possuir itens válidos.","agro360.livestock_diet_invalid");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_nutrition_plans(id,tenant_id,farm_id,herd_id,name,starts_on,ends_on,status,created_by) values(@Id,@TenantId,@FarmId,@HerdId,@Name,@StartsOn,@EndsOn,'ACTIVE',@UserId)",new{Id=id,tenant.TenantId,command.FarmId,command.HerdId,command.Name,command.StartsOn,command.EndsOn,tenant.UserId},t,cancellationToken:ct));foreach(var i in command.Items)await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_nutrition_plan_items(id,tenant_id,plan_id,product_id,quantity_per_day,unit,unit_cost) values(@Id,@TenantId,@Plan,@ProductId,@QuantityPerDay,@Unit,@UnitCost)",new{Id=Guid.CreateVersion7(),tenant.TenantId,Plan=id,i.ProductId,i.QuantityPerDay,i.Unit,i.UnitCost},t,cancellationToken:ct));await Audit(c,t,"create","NutritionPlan",id,command,ct);return id;});
    public Task<IReadOnlyList<dynamic>> ListFeedingsAsync(CancellationToken ct)=>List("select * from agro360.livestock_feedings where tenant_id=@TenantId order by supplied_on desc limit 500",ct);
    public Task<Guid> AddFeedingAsync(FeedingCommand command,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{if(command.HeadCount<=0||command.Items.Count==0||command.Items.Any(i=>i.QuantityPerDay<=0))throw new DomainException("Fornecimento inválido.","agro360.livestock_feeding_invalid");var id=Guid.CreateVersion7();decimal cost=0;foreach(var i in command.Items){await Consume(c,t,command.WarehouseId,i.ProductId,i.QuantityPerDay,i.Unit,id,"FEEDING",ct);cost+=i.QuantityPerDay*i.UnitCost;}await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_feedings(id,tenant_id,plan_id,warehouse_id,supplied_on,head_count,total_cost,cost_per_head,notes,created_by) values(@Id,@TenantId,@PlanId,@WarehouseId,@SuppliedOn,@HeadCount,@Cost,@PerHead,@Notes,@UserId)",new{Id=id,tenant.TenantId,command.PlanId,command.WarehouseId,command.SuppliedOn,command.HeadCount,Cost=cost,PerHead=cost/command.HeadCount,command.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","Feeding",id,command,ct);return id;});
    public Task<IReadOnlyList<dynamic>> ListMilkAsync(CancellationToken ct)=>List("select * from agro360.livestock_milk_production where tenant_id=@TenantId order by produced_on desc limit 500",ct);
    public Task<Guid> AddMilkAsync(MilkProductionCommand command,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{if(command.QuantityLiters<0||command.DiscardedLiters<0||command.DiscardedLiters>command.QuantityLiters)throw new DomainException("Produção ou descarte inválido.","agro360.livestock_production_invalid");var id=Guid.CreateVersion7();await c.ExecuteAsync(new CommandDefinition("insert into agro360.livestock_milk_production(id,tenant_id,farm_id,animal_id,herd_id,produced_on,quantity_liters,discarded_liters,quality,destination,notes,withdrawal_alert,created_by) values(@Id,@TenantId,@FarmId,@AnimalId,@HerdId,@ProducedOn,@QuantityLiters,@DiscardedLiters,cast(@Quality as jsonb),@Destination,@Notes,exists(select 1 from agro360.livestock_animals where tenant_id=@TenantId and id=@AnimalId and withdrawal_until>=@ProducedOn),@UserId)",new{Id=id,tenant.TenantId,command.FarmId,command.AnimalId,command.HerdId,command.ProducedOn,command.QuantityLiters,command.DiscardedLiters,command.Quality,command.Destination,command.Notes,tenant.UserId},t,cancellationToken:ct));await Audit(c,t,"create","MilkProduction",id,command,ct);return id;});
    public Task<IReadOnlyList<dynamic>> WeightGainAsync(CancellationToken ct)=>List("select animal_id,min(occurred_on) initial_date,max(occurred_on) final_date,(array_agg(weight_kg order by occurred_on))[1] initial_weight,(array_agg(weight_kg order by occurred_on desc))[1] final_weight,round(((array_agg(weight_kg order by occurred_on desc))[1]-(array_agg(weight_kg order by occurred_on))[1])/nullif(max(occurred_on)-min(occurred_on),0),4) average_daily_gain from agro360.livestock_handling_events where tenant_id=@TenantId and weight_kg is not null group by animal_id having count(*)>1",ct);
    public async Task<LivestockDashboardDto> DashboardAsync(CancellationToken ct) { try { return await db.InTenantTransactionAsync<LivestockDashboardDto>(async(c,t)=>{using var g=await c.QueryMultipleAsync(new CommandDefinition("select count(*) filter(where status=1),count(*) filter(where status=6),count(*) filter(where status=4 and updated_at>=date_trunc('month',now())),count(*) filter(where withdrawal_until>=current_date) from agro360.livestock_animals where tenant_id=@TenantId; select species name,count(*) value from agro360.livestock_animals where tenant_id=@TenantId and status=1 group by species; select coalesce(category,'NÃO INFORMADA') name,count(*) value from agro360.livestock_animals where tenant_id=@TenantId and status=1 group by category; select count(*) from agro360.livestock_herds where tenant_id=@TenantId and status='ACTIVE' and deleted_at is null; select coalesce(sum(quantity_liters-discarded_liters),0) from agro360.livestock_milk_production where tenant_id=@TenantId and produced_on>=date_trunc('month',current_date); select count(*) filter(where expected_birth_on is not null),count(*) filter(where expected_birth_on between current_date and current_date+interval '60 days') from agro360.livestock_reproduction_cycles where tenant_id=@TenantId and status='ACTIVE'; select count(*) from agro360.livestock_health_events where tenant_id=@TenantId and next_application between current_date and current_date+interval '30 days'; select count(*) filter(where status='IN_USE'),count(*) filter(where status='RESTING') from agro360.livestock_paddocks where tenant_id=@TenantId; select count(*) from agro360.livestock_paddocks p where tenant_id=@TenantId and (select count(*) from agro360.livestock_animals a where a.tenant_id=p.tenant_id and a.paddock_id=p.id and a.status=1)>p.capacity_au; select coalesce(sum(total_cost),0) from agro360.livestock_feedings where tenant_id=@TenantId and supplied_on>=date_trunc('month',current_date); select coalesce(sum(cost_amount),0) from agro360.livestock_health_events where tenant_id=@TenantId and occurred_on>=date_trunc('month',current_date)",new{tenant.TenantId},t,cancellationToken:ct));var a=await g.ReadSingleAsync<dynamic>();var species=(await g.ReadAsync<MetricDto>()).ToArray();var categories=(await g.ReadAsync<MetricDto>()).ToArray();var herds=await g.ReadSingleAsync<long>();var milk=await g.ReadSingleAsync<decimal>();var repro=await g.ReadSingleAsync<dynamic>();var vaccines=await g.ReadSingleAsync<long>();var pastures=await g.ReadSingleAsync<dynamic>();var over=await g.ReadSingleAsync<long>();var nutrition=await g.ReadSingleAsync<decimal>();var health=await g.ReadSingleAsync<decimal>();return new((long)a.count,species,categories,herds,(long)a.count1,(long)a.count2,0,milk,(long)repro.count,(long)repro.count1,vaccines,(long)a.count3,(long)pastures.count,(long)pastures.count1,over,nutrition,health);}, ct); } catch (Exception exception) when (exception is not OperationCanceledException) { InfrastructureLogMessages.LivestockDashboardFailed(logger, tenant.TenantId, exception); throw; } }
    private Task<IReadOnlyList<dynamic>> List(string sql,CancellationToken ct)=>Tx<IReadOnlyList<dynamic>>(async(c,t)=>(await c.QueryAsync(new CommandDefinition(sql,new{tenant.TenantId},t,cancellationToken:ct))).AsList());
    private Task<Guid> Upsert(string table,Guid? id,string columns,string values,string updates,object x,CancellationToken ct)=>Tx<Guid>(async(c,t)=>{var key=id??Guid.CreateVersion7();var args=new DynamicParameters(x);args.Add("Id",key);args.Add("TenantId",tenant.TenantId);args.Add("UserId",tenant.UserId);var sql=id is null?$"insert into {table}(id,tenant_id,{columns},created_at,created_by) values(@Id,@TenantId,{values},now(),@UserId)":$"update {table} set {updates},updated_at=now(),updated_by=@UserId where tenant_id=@TenantId and id=@Id";var n=await c.ExecuteAsync(new CommandDefinition(sql,args,t,cancellationToken:ct));if(n==0)throw new NotFoundException(table,key);await Audit(c,t,id is null?"create":"update",table,key,x,ct);return key;});
    private async Task Consume(NpgsqlConnection c,NpgsqlTransaction t,Guid? warehouse,Guid? product,decimal quantity,string unit,Guid reference,string type,CancellationToken ct){if(warehouse is null&&product is null)return;if(warehouse is null||product is null)throw new DomainException("Depósito e produto devem ser informados juntos.","agro360.inventory_references_required");var row=await c.QuerySingleOrDefaultAsync<dynamic>(new CommandDefinition("select id,available,reserved,average_cost,version,unit from agro360.inventory_stock_balances where tenant_id=@TenantId and warehouse_id=@Warehouse and product_id=@Product for update",new{tenant.TenantId,Warehouse=warehouse,Product=product},t,cancellationToken:ct))??throw new ConflictException("Insumo sem saldo.","agro360.inventory_insufficient_stock");if((decimal)row.available-(decimal)row.reserved<quantity)throw new ConflictException("Estoque insuficiente.","agro360.inventory_insufficient_stock");if(!string.Equals((string)row.unit,unit,StringComparison.OrdinalIgnoreCase))throw new DomainException("Unidade incompatível.","agro360.inventory_unit_mismatch");var balance=(decimal)row.available-quantity;await c.ExecuteAsync(new CommandDefinition("update agro360.inventory_stock_balances set available=@Balance,version=version+1,updated_at=now() where id=@Id and tenant_id=@TenantId and version=@Version; insert into agro360.inventory_stock_movements(id,tenant_id,warehouse_id,product_id,movement_type,quantity,unit,unit_cost,total_cost,reference_type,reference_id,balance_after,average_cost_after,balance_version,occurred_at,created_by) values(@Movement,@TenantId,@Warehouse,@Product,'CONSUMPTION',@Quantity,@Unit,@Cost,@Total,@Type,@Reference,@Balance,@Cost,@NewVersion,now(),@UserId)",new{Balance=balance,Id=(Guid)row.id,tenant.TenantId,Version=(long)row.version,Movement=Guid.CreateVersion7(),Warehouse=warehouse,Product=product,Quantity=quantity,Unit=unit,Cost=(decimal)row.average_cost,Total=quantity*(decimal)row.average_cost,Type=type,Reference=reference,NewVersion=(long)row.version+1,tenant.UserId},t,cancellationToken:ct));}
    private Task Audit(NpgsqlConnection c,NpgsqlTransaction t,string action,string entity,Guid id,object value,CancellationToken ct)=>c.WriteAuditAsync(t,tenant,action,entity,id,null,value,ct);
    private Task<T> Tx<T>(Func<NpgsqlConnection,NpgsqlTransaction,Task<T>> work)=>db.InTenantTransactionAsync(work,CancellationToken.None);
    private Task Tx(Func<NpgsqlConnection,NpgsqlTransaction,Task> work)=>db.InTenantTransactionAsync(work,CancellationToken.None);
    private static int GestationDays(string species)=>species.ToUpperInvariant() switch{"BOVINE" or "BOVINO"=>283,"BUFFALO" or "BUBALINO"=>310,"SHEEP" or "OVINO"=>150,"GOAT" or "CAPRINO"=>150,"SWINE" or "SUINO" or "SUÍNO"=>114,_=>280};
    private static void ValidateWeight(decimal? value){if(value<0)throw new DomainException("Peso não pode ser negativo.","agro360.livestock_weight_invalid");}
}
